"""Tasks written before reasoning in the edge-case step was measured, and scored only once.

Like holdout3, they live outside TASKS so the validator hash stays valid and they
never reach training. Hidden tests check only what each prompt states, and every
prompt states something the visible test does not reach.
"""
from __future__ import annotations

import hashlib
from pathlib import Path

