       NODE_T + APP_T % 'flushQueue' + "test('count', async () => assert.equal(await flushQueue([1, 2], async () => {}), 2));\ntest('order', async () => { const seen = []; await flushQueue([1, 2], (x) => new Promise((ok) => setTimeout(() => { seen.push(x); ok(); }, x === 1 ? 20 : 1))); assert.deepEqual(seen, [1, 2]); });\ntest('stops', async () => { const q = [1, 2, 3]; const seen = []; const n = await flushQueue(q, async (x) => { seen.push(x); if (x === 2) throw new Error('x'); }); assert.equal(n, 1); assert.deepEqual(q, [2, 3]); assert.deepEqual(seen, [1, 2]); });\ntest('none', async () => assert.equal(await flushQueue([], async () => {}), 0));\n",
